  class OllamaClient { private string $host; private string $model; public function __construct(string $host = 'http://localhost:11434', string $model = 'llama3') { $this->host = $host; $this->model = $model; } public function generatePrompt(string $prompt, string $systemContext = ''): array { $ch = curl_init("{$this->host}/api/generate"); curl_setopt($ch, CURLOPT_RETURNTRANSFER, true); curl_setopt($ch, CURLOPT_POST, true); curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, 2); curl_setopt($ch, CURLOPT_TIMEOUT, 5); curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode([ 'model' => $this->model, 'prompt' => $systemContext ? "Context: {$systemContext}\n\nUser: {$prompt}" : $prompt, 'stream' => false, ])); $response = curl_exec($ch); $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch); if ($httpCode === 200 && $response) { $data = json_decode($response, true); return [ 'provider' => 'ollama', 'model' => $this->model, 'response' => $data['response'] ?? '', 'status' => 'success' ]; } return [ 'provider' => 'veltrion-ai-engine', 'model' => 'veltrion-rule-based-v1', 'response' => "Análisis de Inteligencia de Veltrion PHP (Contexto de Arquitectura Activo):\n\n" . "Basado en las directrices del proyecto y los documentos en docs/:\n" . "1. Para la consulta '{$prompt}', la recomendación arquitectónica es utilizar un UseCase encapsulado con el patrón Repository.\n" . "2. Puedes generar el módulo ejecutando: php cli make:crud <NombreModulo>\n" . "3. Para realizar auditorías automatizadas ejecuta: php cli agent run all", 'status' => 'fallback' ]; } } 